//! The names a fence may give a language, and the grammar each one gets.
//!
//! This file is generated. Do not edit it by hand. It comes from GitHub
//! Linguist's `languages.yml` (MIT licence, fetched on 2026-11-02), by
//! the ignored test `generate_the_language_table` in
//! `languages/tests.rs`, which also holds kiri's own additions: run it
//! again to change the table.
//!
//! A language's name and aliases come first, then kiri's additions, then
//! every language's file extensions, and an earlier one keeps a name
//! that a later one also wants. Each name goes to a grammar of
//! two-face's syntax set. The table is sorted, so a name is found by
//! binary search.

/// The grammar for a fence's language, in the name two-face's set has
/// for it, or `None` if the table does not know the name.
pub(super) fn grammar(token: &str) -> Option<&'static str> {
    let token = token.to_lowercase();
    TABLE
        .binary_search_by_key(&token.as_str(), |(name, _)| name)
        .ok()
        .map(|index| TABLE[index].1)
}

